svg.script:

(function() {
  var svg = document.documentElement,
    stopped = false;
  var act = {
    play: function() {
      if (stopped || svg.animationsPaused()) {
        stopped = false;
        svg.unpauseAnimations();
      } else {
        svg.setCurrentTime(0);
      }
    },
    pause: function() {
      svg.pauseAnimations();
    },
    resume: function() {
      stopped = false;
      svg.unpauseAnimations();
    },
    reset: function() {
      stopped = false;
      svg.setCurrentTime(0);
      svg.unpauseAnimations();
    },
    stop: function() {
      svg.setCurrentTime(0);
      svg.pauseAnimations();
      stopped = true;
    }
  };
  document.querySelectorAll("#controls .btn").forEach(function(b) {
    b.addEventListener("click", function() {
      act[b.getAttribute("data-act")]();
    });
  });
})();
